import json

POLICY_FILE = "Payroll/correction-policy.json"
DEFAULT_POLICY = "next_pay_run"
VALID_POLICIES = {"revert", "next_pay_run", "unscheduled_pay_run"}

def pr_read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default

policy_config = pr_read_json(POLICY_FILE) or {}
default_policy = str(policy_config.get("default_policy") or DEFAULT_POLICY)
if default_policy not in VALID_POLICIES:
    default_policy = DEFAULT_POLICY
overrides = policy_config.get("employee_overrides") or {}

recon = api.connectors.invoke(server="xero-payroll-au", tool="get_hours_reconciliation", args={})
pay_run = recon.get("payRun") or {}
pay_run_period = str(pay_run.get("periodText") or "")
employees = recon.get("employees") or []

POLICY_NOTES = {
    "revert": "This client's policy is to revert the pay run. Xero has no API to unpost a posted pay run, so this needs to be done manually in Xero (or via Xero support if it's already been paid). Mark this item Done once that's handled.",
    "next_pay_run": "This client's policy is to correct this in the next pay run. Mark this item Done to confirm -- you'll then get exact instructions for what to adjust, since this automation can't write directly to a Xero payslip yet.",
    "unscheduled_pay_run": "This client's policy is to correct this via an unscheduled pay run. Mark this item Done to confirm -- you'll then get exact instructions for what to adjust, since this automation can't write directly to a Xero payslip yet.",
}

proposed_count = 0
for emp in employees:
    if emp.get("category") != "both" or not emp.get("hasVariance"):
        continue
    employee_id = str(emp.get("employeeId") or "")
    employee_name = str(emp.get("name") or "Unknown employee")
    policy = str(overrides.get(employee_id) or default_policy)
    if policy not in VALID_POLICIES:
        policy = default_policy

    segments = [s for s in (emp.get("segments") or []) if s.get("hasVariance")]
    lines = "\n".join(
        f"- {s.get('name')}: timesheet {s.get('timesheetHours')}h vs payroll {s.get('payrollHours')}h (variance {s.get('variance')}h)"
        for s in segments
    )

    human_text = (
        f"Employee: {employee_name}\n"
        f"Pay run period: {pay_run_period}\n"
        f"Total variance: {emp.get('variance')}h (timesheet {emp.get('timesheetHours')}h vs payroll {emp.get('payrollHours')}h)\n"
        f"By earnings rate:\n{lines}\n\n"
        f"Policy applied: {policy.replace('_', ' ')}\n{POLICY_NOTES[policy]}"
    )

    correction_data = {
        "employee_id": employee_id,
        "employee_name": employee_name,
        "pay_run_period": pay_run_period,
        "policy": policy,
        "segments": segments,
    }
    description = human_text + "\n---CORRECTION-DATA---\n" + json.dumps(correction_data)
    title = f"Payroll correction needed: {employee_name} -- {emp.get('variance')}h variance ({policy.replace('_', ' ')})"

    api.workq.create(
        title=title,
        scope="org",
        description=description,
        labels=["payroll-correction", policy],
    )
    proposed_count += 1
